cd "$TMPDIR"; python3 << 'EOF'
import re
def last_time(fn):
    times=[]
    for line in open(fn, encoding='utf-8', errors='replace'):
        m = re.match(r'(\d+):(\d+):(\d+)', line.strip())
        if m: times.append(int(m.group(1))*3600+int(m.group(2))*60+int(m.group(3)))
    return max(times)
print("Boogeyman SRT last ts (s):", last_time('Boogeyman.2005.1080p.BluRay.x264-BestHD-English.srt'))
print("Exorcist III SRT last ts (s):", last_time('The Exorcist III-English.srt'))
print("Boogeyman 89 min in s:", 89*60, " Exorcist III 110 min:", 110*60)
EOF

